package acl

import (
	"testing"
)

// FuzzParsePacket fuzzes the ParsePacket function.
func FuzzParsePacket(f *testing.F) {
	// Add seed corpus
	f.Add([]byte{0x45, 0x00, 0x00, 0x28, 0x00, 0x00, 0x00, 0x00, 0x40, 0x06, 0x00, 0x00, 0x0a, 0x00, 0x00, 0x01, 0x0a, 0x00, 0x00, 0x02, 0x30, 0x39, 0x00, 0x16, 0x00, 0x00, 0x00, 0x00, 0x50, 0x02, 0x20, 0x00})                                                                                                                         // IPv4 TCP SYN
	f.Add([]byte{0x45, 0x00, 0x00, 0x1c, 0x00, 0x00, 0x00, 0x00, 0x40, 0x11, 0x00, 0x00, 0x0a, 0x00, 0x00, 0x01, 0x0a, 0x00, 0x00, 0x02, 0x30, 0x39, 0x00, 0x35, 0x00, 0x08, 0x00, 0x00})                                                                                                                                                 // IPv4 UDP
	f.Add([]byte{0x45, 0x00, 0x00, 0x1c, 0x00, 0x00, 0x00, 0x00, 0x40, 0x01, 0x00, 0x00, 0x0a, 0x00, 0x00, 0x01, 0x0a, 0x00, 0x00, 0x02, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00})                                                                                                                                           // IPv4 ICMP Echo Request
	f.Add([]byte{0x60, 0x00, 0x00, 0x00, 0x00, 0x14, 0x06, 0x40, 0x20, 0x01, 0x0d, 0xb8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x20, 0x01, 0x0d, 0xb8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, 0x30, 0x39, 0x00, 0x16, 0x00, 0x00, 0x00, 0x00, 0x50, 0x02, 0x20, 0x00}) // IPv6 TCP SYN
	f.Add([]byte{0x60, 0x00, 0x00, 0x00, 0x00, 0x08, 0x3a, 0x40, 0x20, 0x01, 0x0d, 0xb8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x20, 0x01, 0x0d, 0xb8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00})                         // IPv6 ICMPv6 Echo Request
	f.Add([]byte{0x45, 0x00, 0x00, 0x14, 0x00, 0x01, 0x20, 0x00, 0x40, 0x06, 0x00, 0x00, 0x0a, 0x00, 0x00, 0x01, 0x0a, 0x00, 0x00, 0x02})                                                                                                                                                                                                 // IPv4 fragment

	f.Fuzz(func(t *testing.T, data []byte) {
		_, _, _ = ParsePacket(data)
	})
}
